function updateDetectionControls(){
  const item=active?.detection?.questions.find(q=>q.id===$('detected-question').value);
  $('detected-question').disabled=busy||rendering||!active?.detection?.questions.length;
  $('preview-detected').disabled=busy||rendering||!item;
  $('add-detected').disabled=busy||rendering||!item||(active?.kind==='scheme'?!questions.some(q=>q.id===selected):questions.some(q=>q.detectedKey===active.id+':'+item.id));
}
function drawDetectedQuestions(){
  const select=$('detected-question');select.replaceChildren();
  const found=active?.detection?.questions||[];
  const first=make('option',found.length?'Choose a question…':active?'No questions detected':'Add a PDF to read its questions');first.value='';select.append(first);
  for(const question of found){const from=question.parts[0].page,to=question.parts.at(-1).page;const option=make('option',question.label+' · p. '+from+(to!==from?'–'+to:'')+(question.summary?' · '+question.summary.slice(0,85):''));option.value=question.id;select.append(option);}
  const result=active?.detection;
  $('detection-info').textContent=!active?'Add a PDF to read its numbered question headings.':!result?.characters?'No readable text was found. This may be a scanned PDF; select question regions manually.':!found.length?'Text was read, but no reliable numbered headings were found. Select regions manually.':found.length+' question'+(found.length===1?'':'s')+' detected from PDF text. All detected sections are included when you add a question.'+(result.failures?' Some pages could not be read; check the boundaries carefully.':'');
  updateDetectionControls();
}
function detectedItem(){return active?.detection?.questions.find(q=>q.id===$('detected-question').value);}
$('detected-question').onchange=()=>{const item=detectedItem();if(item){const from=item.parts[0].page,to=item.parts.at(-1).page;$('detection-info').textContent=item.label+' · '+item.parts.length+' section'+(item.parts.length===1?'':'s')+' · page'+(from===to?' ':'s ')+from+(to===from?'':'–'+to)+'. '+item.summary;status('Preview this question to check its boundaries, then add it to your set.');}updateDetectionControls();};
