  if(!q.partChoices){box.append(make('p','Find printed labels such as (a), (b) or 06.1, then choose the parts to include.','hint'),action('Find question parts',async()=>{if(busy)return;busy=true;controls();try{q.partChoices=await findQuestionParts(q.parts,q.sourceNumber??q.parts.find(p=>p.sourceNumber)?.sourceNumber);drawQuestions();status(q.partChoices.found?'Parts found. Untick any part you want to omit; check its boundaries with View.':'No readable part labels found. Use manual regions to include only the content you need.');}catch(error){status('Could not find question parts: '+error.message);}finally{busy=false;drawQuestions();}}));}
